<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">ORDERS</a></li>
              <li class="breadcrumb-item active" aria-current="page">CANCELLATION</li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <global-search-field v-model:filterValue="filter" />
    <div class="d-flex align-items-center justify-content-between mb-3 mt-3">
      <h3 class="text-center m-0 flex-grow-1" v-if="!mobileView">
        ORDER CANCELLATION RERQUEST
      </h3>
    </div>

    <div class="mb-3 d-flex justify-content-end align-items-center gap-2">
      <div style="display: inline-block; min-width: 200px">
        <input
          type="number"
          class="form-control"
          v-model="lpoNumber"
          placeholder="Enter Order Number"
        />
      </div>
    </div>

    <div class="d-flex justify-content-end flex-wrap gap-2">
      <button class="btn btn-success" @click="printReport()">
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="26"
          height="26"
          fill="currentColor"
          class="bi bi-printer"
          viewBox="0 0 16 16"
        >
          <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1" />
          <path
            d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1"
          />
        </svg>
      </button>
      <button class="btn btn-success fs-6" @click="exportToExcel()" title="Export Excel">
        <i class="bi bi-file-earmark-spreadsheet"></i>
      </button>

      <button class="btn btn-primary" @click="getOrderCancellations()">Refresh</button>
    </div>

    <div class="row layout-top-spacing">
      <div v-if="loading" v-html="tableShimmer()"></div>
      <div v-else class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
        <div class="panel p-0">
          <div class="custom-table table3">
            <v-client-table
              :data="filteredData"
              :columns="columns"
              :options="table_option"
            >
              <template #status="props">
                <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
              </template>
              <template #requisition="props">
                <router-link
                  v-if="props.row.type === 'Labour Request'"
                  class="text-primary"
                  :to="`/approval/${props.row.requisition}`"
                  title="Click to see requisition"
                  >{{ props.row.requisition }}</router-link
                >
                <router-link
                  v-else
                  class="text-primary"
                  :to="`/requisition/${props.row.requisition}`"
                  title="Click to see requisition"
                  >{{ props.row.requisition }}</router-link
                >
              </template>
              <template #actions="props">
                <a
                  @click="getApprovalChain(props.row)"
                  data-bs-toggle="modal"
                  data-bs-target="#approval"
                  href="javascript:void(0);"
                  class="text-primary me-2"
                >
                  <i class="bi bi-eye text-primary fs-4"></i>
                </a>

                <a
                  v-if="
                    user_permissions.includes('can_print_lpo') &&
                    (props.row?.status?.name === 'approved' ||
                      props.row?.status?.name === 'paid' ||
                      user_permissions.includes('is_programmer'))
                  "
                  href="javascript:void(0);"
                  @click="printGeneralOrder(props.row, props.row.vendor_data)"
                  class="me-2"
                >
                  <i class="bi bi-printer text-success fs-4"></i>
                </a>

                <a
                  v-if="
                    user_permissions.includes('can_print_lpo') &&
                    (props.row?.status?.name === 'approved' ||
                      props.row?.status?.name === 'paid' ||
                      user_permissions.includes('is_programmer'))
                  "
                  href="javascript:void(0);"
                  @click="downloadVoucherPDF(props.row, props.row.vendor_data)"
                  class="text-dark"
                >
                  <i class="bi bi-download fs-4"></i>
                </a>

                <a
                  v-if="user_permissions.includes('can_delete_lpo')"
                  href="javascript:void(0);"
                  @click="deleteApproval(props.row)"
                  class="text-danger"
                >
                  <i class="bi bi-trash fs-4"></i>
                </a>

                <a
                  href="javascript:void(0);"
                  class="text-dark position-relative ms-2"
                  @click="
                    getApprovalChain(props.row);
                    getLogs();
                  "
                  data-bs-target="#note-modal"
                  data-bs-toggle="modal"
                >
                  <i class="bi bi-journal-bookmark-fill text-primary fs-4"></i>
                  <span
                    v-if="props.row.approval_logs > 0"
                    class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                    style="font-size: 9px; min-width: 16px; padding: 2px 4px"
                  >
                    {{ props.row.approval_logs }}
                  </span>
                </a>

                <!-- modal trigger only -->
              </template>
            </v-client-table>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- Modal -->
  <div
    class="modal fade mymodal"
    id="approval"
    tabindex="-1"
    role="dialog"
    aria-labelledby="exampleModalLabel"
    aria-hidden="true"
    data-bs-backdrop="false"
    ref="approvalModal"
  >
    <div class="modal-dialog modal-fullscreen" role="document">
      <div class="modal-content">
        <div class="modal-header">
          <h5 class="modal-title" id="exampleModalLabel">Approval Chain</h5>
          <button
            type="button"
            data-dismiss="modal"
            data-bs-dismiss="modal"
            aria-label="Close"
            class="btn-close"
            @click="clearForm()"
            id="close-approval-modal"
          ></button>
        </div>

        <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
          <div class="panel p-0">
            <div class="custom-table table3 table-responsive">
              <table class="table table-bordered table-striped">
                <thead>
                  <tr>
                    <th>Order No</th>
                    <th>Requester</th>
                    <th>Date Requested</th>
                    <th>Purpose</th>
                    <th>Approval Chain</th>
                    <th v-if="item.project">Project</th>
                    <th v-if="item.vendor">
                      <span v-if="item?.type?.toLowerCase().includes('voucher')">
                        Beneficiary
                      </span>
                      <span v-else> Vendor </span>
                    </th>
                    <th>Awaits</th>
                    <th>Cost</th>
                    <th v-if="user_permissions.includes('can_print_lpo')">Action</th>
                    <th>Delete</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td>{{ item?.order }}</td>
                    <td>{{ item.requester }}</td>
                    <td>{{ item?.date }}</td>
                    <td>{{ item?.type }}</td>
                    <td>{{ item?.purpose }}</td>
                    <td v-if="item.project">{{ item.project }}</td>
                    <td v-if="item.vendor">{{ item.vendor }}</td>
                    <td>{{ item?.awaits }}</td>
                    <td>{{ item?.cost }}</td>
                    <td v-if="user_permissions.includes('can_print_lpo')">
                      <a
                        v-if="
                          user_permissions.includes('can_print_lpo') &&
                          (item?.status?.name === 'approved' ||
                            item?.status?.name === 'paid' ||
                            user_permissions.includes('is_programmer'))
                        "
                        href="javascript:void(0);"
                        @click="printGeneralOrder(item, item.vendor_data)"
                        class="text-success me-2"
                      >
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="24"
                          height="24"
                          fill="currentColor"
                          class="bi bi-printer"
                          viewBox="0 0 16 16"
                        >
                          <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1z" />
                          <path
                            d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2H5zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4V3zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2H5zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1z"
                          />
                        </svg>
                      </a>
                      <button
                        @click="toggleApproval()"
                        v-if="
                          item.purpose === 'Labour Request' &&
                          user_permissions.includes('can_create_labour_voucher')
                        "
                        class="btn btn-outline-primary"
                      >
                        Create Voucher
                      </button>
                      <router-link
                        :to="`/report/labour-payments/${item.id}`"
                        v-if="item.purpose === 'Labour Request'"
                        class="text-primary"
                      >
                        view History
                      </router-link>
                    </td>
                    <td>
                      <a
                        v-if="user_permissions.includes('can_delete_lpo')"
                        href="javascript:void(0);"
                        @click="deleteApproval(item)"
                        class="text-danger"
                      >
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="24"
                          height="24"
                          fill="currentColor"
                          class="bi bi-trash"
                          viewBox="0 0 16 16"
                        >
                          <path
                            d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"
                          />
                          <path
                            d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"
                          />
                        </svg>
                      </a>
                    </td>
                  </tr>
                  <tr v-if="item.description">
                    <td colspan="8">
                      <b> Brief Description : </b>
                      {{ item.description }}
                      <span v-if="approval_description">
                        ( {{ approval_description }} )</span
                      >
                    </td>
                  </tr>
                  <tr v-if="item.remark">
                    <td colspan="8"><b> Remark : </b> {{ item.remark }}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div class="modal-body">

          <!-- Notes preview -->
<div class="mt-3 mb-3">
  <h5 class="text-center" style="font-size:1rem;">
    Notes
    <span v-if="logs.length" class="badge bg-danger rounded-pill">{{ logs.length }}</span>
  </h5>

  <div v-if="logsLoading" class="text-center py-2">
    <span v-html="waitIndicator()"></span>
  </div>


  <div v-else class="d-flex flex-column gap-2" >
    <template v-for="log in logs" :key="log.id">
      <!-- parent -->
      <div class="d-flex gap-2 align-items-start">
        <div class="avatar-circle avatar-sm flex-shrink-0"
             :style="{ background: avatarBg(log.reporter?.name), color: avatarColor(log.reporter?.name) }">
          {{ log.reporter?.name?.charAt(0)?.toUpperCase() }}
        </div>
        <div class="flex-grow-1">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <strong style="font-size:13px;">{{ log.reporter?.name }}</strong>
            <small class="text-muted">{{ formatDate(log.created_at) }}</small>
          </div>
          <p style="font-size:13px;margin:0;">{{ log.description }}</p>
        </div>
      </div>

      <!-- replies (level 2), flattened, indented -->
      <div v-for="reply in log.replies || []" :key="reply.id" class="d-flex gap-2 align-items-start ms-4">
        <div class="avatar-circle avatar-xs flex-shrink-0"
             :style="{ background: avatarBg(reply.reporter?.name), color: avatarColor(reply.reporter?.name) }">
          {{ reply.reporter?.name?.charAt(0)?.toUpperCase() }}
        </div>
        <div class="flex-grow-1">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <strong style="font-size:12px;">{{ reply.reporter?.name }}</strong>
            <small class="text-muted" style="font-size:11px;">{{ formatDate(reply.created_at) }}</small>
          </div>
          <p style="font-size:12px;margin:0;">{{ reply.description }}</p>
        </div>
      </div>

      <!-- nested replies (level 3), flattened further -->
      <div v-for="reply in log.replies || []" :key="'n-' + reply.id">
        <div v-for="nested in reply.replies || []" :key="nested.id" class="d-flex gap-2 align-items-start ms-5">
          <div class="avatar-circle avatar-xs flex-shrink-0"
               :style="{ background: avatarBg(nested.reporter?.name), color: avatarColor(nested.reporter?.name) }">
            {{ nested.reporter?.name?.charAt(0)?.toUpperCase() }}
          </div>
          <div class="flex-grow-1">
            <div class="d-flex align-items-center gap-2 flex-wrap">
              <strong style="font-size:11px;">{{ nested.reporter?.name }}</strong>
              <small class="text-muted" style="font-size:10px;">{{ formatDate(nested.created_at) }}</small>
            </div>
            <p style="font-size:11px;margin:0;">{{ nested.description }}</p>
          </div>
        </div>
      </div>
    </template>
  </div>

  <div class="text-center mt-1">
    <a href="javascript:void(0);" class="btn btn-outline-primary " @click="openNoteModal()">Add Notes</a>
  </div>
</div>
     <!-- logs for an order -->


          <!-- In your modal-body, replace the v-if/v-else with this -->
          <div class="my-4">
            <!-- <div v-if="loading_spinner" v-html="waitIndicator()"></div> -->

            <!-- ALWAYS mounted, just hidden while loading -->
            <div :style="{ display: loading_spinner ? 'none' : 'block' }">
              <h4 class="text-center" style="font-size: 1.3rem">
                APPROVAL CHAIN FOR CANCELLATION
              </h4>
              <entryApprovalBlock
                :key="componentKey"
                :type="selectedType"
                :entry_id="selectedId"
                @loaded="handleEntry"
                @submit="handleSubmit"
                @loading="loading_spinner = $event"
              />
            </div>
          </div>

          <!-- approval items starts -->
          <h4 class="text-center my-2" style="font-size: 1.3rem">APPROVAL ITEMS</h4>
          <div class="d-flex justify-content-center mb-3">
            <input
              v-if="create_approval"
              type="text"
              class="form-control"
              style="max-width: 350px; font-size: 1rem"
              placeholder="Enter Brief Description "
              v-model="description"
            />
          </div>
          <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
            <div class="panel p-0">
              <div class="custom-table table3 table-responsive">
                <table class="table table-bordered table-striped">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Item</th>
                      <th>Decription</th>
                      <th>Quantity</th>
                      <th>Unit</th>
                      <th>Rate</th>
                      <th>Total</th>
                      <th>Receiver</th>
                      <th v-if="create_approval" class="text-center">select</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr v-for="reqItem in requisitionItems">
                      <td>{{ reqItem.order_item_id }}</td>
                      <td>{{ reqItem.item }}</td>
                      <td>
                        <router-link
                          class="btn btn-outline-primary"
                          :to="`/requisition-budget/${reqItem.requisition_items.item_id}`"
                          v-if="
                            item.requisition_type === 'budget' &&
                            !reqItem.requisition_items.asset_id
                          "
                        >
                          {{ reqItem.description }}
                        </router-link>
                        <span v-else>
                          <span v-if="reqItem.selected">
                            {{ reqItem.description }} (
                            {{ reqItem.request_description }} )
                          </span>
                          <span v-else>
                            {{ reqItem.description }}
                          </span>
                        </span>
                      </td>
                      <td @click="editApprovalItem(reqItem.id)">
                        {{ reqItem.quantity }}
                        <span v-if="reqItem?.requested_sum">
                          <br />
                          Requested : {{ reqItem?.requested_sum }}
                          <br />
                          Balance :{{
                            (reqItem.quantity - reqItem?.requested_sum).toFixed(2)
                          }}
                        </span>

                        <span v-if="reqItem.selected">
                          <br />Requesting : {{ reqItem.requesting_quantity }}
                        </span>
                        <input
                          v-if="edit_item == reqItem.id"
                          type="number"
                          class="form-control"
                          placeholder="Quantity"
                          step="any"
                          v-model="reqItem.quantity"
                        />
                      </td>
                      <td>
                        {{ reqItem.requisition_items.units }}
                      </td>
                      <td @click="editApprovalItem(reqItem.id)">
                        {{ reqItem.rate }}
                        <input
                          v-if="edit_item == reqItem.id"
                          type="number"
                          class="form-control"
                          placeholder="Quantity"
                          step="any"
                          v-model="reqItem.rate_original"
                        />
                      </td>
                      <td>
                        <span>
                          <!-- {{ reqItem.total }}<br> -->
                          {{ formatNumber(reqItem.quantity * reqItem.rate_original)
                          }}<br />
                        </span>
                        <span v-if="reqItem.selected">
                          Requesting :
                          {{
                            formatNumber(
                              reqItem.requesting_quantity * reqItem.rate_original
                            )
                          }}
                        </span>
                      </td>
                      <td>{{ reqItem.receiver ?? reqItem.beneficiary }}</td>
                      <td v-if="create_approval" class="text-center">
                        <svg
                          v-if="reqItem.selected"
                          @click="reqItem.selected = !reqItem.selected"
                          xmlns="http://www.w3.org/2000/svg"
                          width="26"
                          height="26"
                          fill="currentColor"
                          class="bi bi-check2-circle"
                          viewBox="0 0 16 16"
                        >
                          <path
                            d="M2.5 8a5.5 5.5 0 0 1 8.25-4.764.5.5 0 0 0 .5-.866A6.5 6.5 0 1 0 14.5 8a.5.5 0 0 0-1 0 5.5 5.5 0 1 1-11 0"
                          />
                          <path
                            d="M15.354 3.354a.5.5 0 0 0-.708-.708L8 9.293 5.354 6.646a.5.5 0 1 0-.708.708l3 3a.5.5 0 0 0 .708 0z"
                          />
                        </svg>

                        <svg
                          v-else
                          @click="reqItem.selected = !reqItem.selected"
                          xmlns="http://www.w3.org/2000/svg"
                          width="26"
                          height="26"
                          fill="currentColor"
                          class="bi bi-circle"
                          viewBox="0 0 16 16"
                        >
                          <path
                            d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14m0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16"
                          />
                        </svg>
                        <input
                          v-if="reqItem.selected"
                          type="number"
                          placeholder="enter quantity"
                          class="form-control w-75"
                          step="any"
                          v-model="reqItem.requesting_quantity"
                          @input="
                            reqItem.requesting_quantity = enforceMax(
                              reqItem.requesting_quantity,
                              (reqItem.quantity - reqItem?.requested_sum).toFixed(2)
                            )
                          "
                        />

                        <input
                          v-if="reqItem.selected"
                          type="text"
                          placeholder="enter Description"
                          class="form-control w-75 mt-1"
                          v-model="reqItem.request_description"
                        />
                        <input
                          v-if="reqItem.selected"
                          type="text"
                          placeholder="enter Beneficiary"
                          class="form-control w-75 mt-1"
                          v-model="reqItem.receiver"
                        />
                      </td>
                      <td>
                        <router-link
                          :to="`/asset/profile/${reqItem.requisition_items.asset_id}`"
                          v-if="reqItem.requisition_items.asset_id"
                          class="me-2"
                        >
                          <button class="btn btn-outline-primary me-2">
                            Asset Profile
                          </button>
                        </router-link>

                        <router-link
                          :to="`/requisition-budget/${reqItem.requisition_items.item_id}`"
                          v-if="item.requisition_type === 'budget'"
                        >
                          <button class="btn btn-outline-primary me-2">Budget</button>
                        </router-link>
                        <router-link
                          :to="`/jobcard/outside/${reqItem.requisition_items.requisition_type.item_id}`"
                          v-if="item.requisition_type === 'jobcard'"
                          class="me-2"
                        >
                          <button class="btn btn-outline-primary me-2">Jobcard</button>
                        </router-link>
                        <router-link
                          :to="`/subcontractor/${approval.subcontractor_agreement_id}`"
                          v-if="approval.subcontractor_agreement_id"
                        >
                          <button class="btn btn-outline-primary me-2">
                            Subcontractor
                          </button>
                        </router-link>
                        <router-link
                          :to="`${reqItem.category.path}/${reqItem.requisition_items.category_ref_id}`"
                          v-if="
                            reqItem.category &&
                            reqItem.category.name !== 'STATEMENT OF ACCOUNTS'
                          "
                        >
                          <button class="btn btn-outline-dark me-2">
                            {{ reqItem.category.name }}
                          </button>
                        </router-link>
                        <a
                          href="javascript:void(0);"
                          v-if="
                            reqItem.category &&
                            reqItem.category.name === 'STATEMENT OF ACCOUNTS'
                          "
                          @click="
                            openBinCard();
                            getStatement(reqItem.requisition_items.category_ref_id);
                          "
                        >
                          <button type="button" class="btn btn-outline-dark me-2">
                            STATEMENT OF ACCOUNTS
                          </button>
                        </a>
                        <button
                          v-if="
                            user_permissions.includes('can_print_lpo') &&
                            (item.status.name === 'approved' ||
                              item.status.name === 'paid' ||
                              user_permissions.includes('is_programmer'))
                          "
                          class="btn btn-outline-success me-2"
                          @click="printOrder(reqItem, item)"
                        >
                          <svg
                            xmlns="http://www.w3.org/2000/svg"
                            width="24"
                            height="24"
                            fill="currentColor"
                            class="bi bi-printer"
                            viewBox="0 0 16 16"
                          >
