  noteEl.addEventListener(
    "hidden.bs.modal",
    () => {
      document.body.classList.add("modal-open");
      approvalEl.classList.add("show");
      approvalEl.style.display = "block";
    },
    { once: true }
  );
};

const logs = ref([]);
const logsLoading = ref(false);
const newMessage = ref("");
const replyingTo = ref(null);

const getLogs = async (source, source_id) => {
  logsLoading.value = true;
  logs.value = [];
  try {
    const response = await axiosInstance.get(
      `logs?source=LPO&source_id=${approval.value.approval_id}`
    );
    logs.value = response.data;
  } catch (error) {
    showError(error.message);
  } finally {
    logsLoading.value = false;
  }
};

const submitting = ref(false);
const submitLog = async (parent_id = null) => {
  submitting.value = true;
  if (!newMessage.value.trim()) return;
  try {
    await axiosInstance.post("logs", {
      parent_id,
      type: "MESSAGE",
      reporter_id: user_id,
      source: "LPO",
      source_id: approval.value.approval_id,
      module: "LPO & VOUCHERS",
      description: newMessage.value.trim(),
      status_id: 1,
    });
    newMessage.value = "";
    replyingTo.value = null;
    getLogs(item.value.type, item.value.id);
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    submitting.value.false;
  }
};

const currentUserName = computed(() => JSON.parse(localStorage.getItem("user")).name);

const avatarPalette = [
  { bg: "#CECBF6", color: "#3C3489" },
  { bg: "#B5D4F4", color: "#0C447C" },
  { bg: "#9FE1CB", color: "#085041" },
  { bg: "#FAC775", color: "#633806" },
  { bg: "#F4C0D1", color: "#72243E" },
  { bg: "#C0DD97", color: "#3B6D11" },
];
const avatarBg = (name) =>
  avatarPalette[(name?.charCodeAt(0) ?? 0) % avatarPalette.length].bg;
const avatarColor = (name) =>
  avatarPalette[(name?.charCodeAt(0) ?? 0) % avatarPalette.length].color;

const editingLog = ref(null);
const editText = ref("");

const startEdit = (log) => {
  editingLog.value = log.id;
  editText.value = log.description;
};

const cancelEdit = () => {
  editingLog.value = null;
  editText.value = "";
};

const updateLog = async (log) => {
  if (!editText.value.trim()) return;
  submitting.value = true;
  try {
    await axiosInstance.put(`logs/${log.id}`, {
      description: editText.value.trim(),
    });
    showMessage("Note updated");
    editingLog.value = null;
    editText.value = "";
    getLogs();
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    submitting.value = false;
  }
};
watch(lpoNumber, (newVal) => {
  date.value = "";
  if (newVal !== null && newVal !== undefined && newVal !== "") {
    getOrderCancellations();
  }
});

const binCardColumn = ref(["SNo", "date", "ref_no", "remark", "Dr", "Cr", "balance"]);
const bincard = ref([]);
const statementName = ref("");
const statementIssuer = ref("");
const finalBalance = ref("0.00");
const totalReceived = ref("0.00");
const totalIssued = ref("0.00");

const getStatement = async (id) => {
  loading.value = true;

  try {
    const response = await axiosInstance.get(
      `bin-cards?no_store_item=1&bincard_id=${id}`
    );
    const data = response.data[0];
    statementName.value = data.name || "";
    statementIssuer.value = data.issuer?.name || "N/A";

    let runningBalance = 0;
    let totalReceivedAmount = 0;
    let totalIssuedAmount = 0;

    bincard.value = data.items.map((item, index) => {
      const received = parseFloat(item.received) || 0;
      const issued = parseFloat(item.issued) || 0;

      totalReceivedAmount += received;
      totalIssuedAmount += issued;
      runningBalance += received - issued;

      return {
        id: item.id,
        SNo: index + 1,
        date: formatDate(item.date),
        ref_no: item.ref_no || "--",
        Dr: received ? formatNumber(received) + " " + (data.unit || "") : "--",
        Cr: issued ? formatNumber(issued) + " " + (data.unit || "") : "--",
        balance: formatNumber(runningBalance) + " " + (data.unit || ""),
        remark: item.remark || "--",
        authorized_by: item.issuer?.name || "N/A",
      };
    });

    finalBalance.value = formatNumber(runningBalance) + " " + (data.unit || "");

    totalReceived.value = formatNumber(totalReceivedAmount) + " " + (data.unit || "");

    totalIssued.value = formatNumber(totalIssuedAmount) + " " + (data.unit || "");
  } catch (error) {
    console.log(error);
    showError(error.message);
  } finally {
    loading.value = false;
  }
};

const openBinCard = () => {
  const viewStoreEl = document.getElementById("approval");
  const noteEl = document.getElementById("binCardModal");

  const noteModal = Modal.getOrCreateInstance(noteEl);
  noteModal.show();

  noteEl.addEventListener(
    "hidden.bs.modal",
    () => {
      document.body.classList.add("modal-open");
      viewStoreEl.classList.add("show");
      viewStoreEl.style.display = "block";
    },
    { once: true }
  );
};
